def hub_transport():
    name='Prochitecture Streets / Supplied ordinary Coons hub v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Geometry','Mouths'):g.socket(key,'NodeSocketGeometry')
    g.socket('Rows','NodeSocketInt');g.socket('Input Valid','NodeSocketBool');g.socket('Hub','NodeSocketVector')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
    g.socket('Hub Shift','NodeSocketVector','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    source=inp.outputs['Geometry'];half=c.V(g,inp.outputs['Rows'])/2.
    chart,u,v=g.separate(c.named(g,'st_cq_key','FLOAT_VECTOR'));eq=lambda a,b:g.math('COMPARE',a,b)
    hubs=c._select(g,source,eq(chart,-2.));old=c._vec(g,c._sample(g,hubs,g.position(),0,'FLOAT_VECTOR'))
    delta=c._sub(c._vec(g,inp.outputs['Hub']),old)
    weight=c.choose(g,g.math('LESS_THAN',chart,-2.5),u*v/(half*half),
        c.choose(g,eq(chart,-1.),v/half,c.choose(g,eq(chart,-2.),1.,0.)))
    x,y,z=g.separate(g.position())
    result=g.setpos(source,g.xyz(x+weight*delta[0],y+weight*delta[1],z))
    valid=c.V(g,inp.outputs['Input Valid'])*eq(c._count(g,hubs),1.)
    for key,value in (('Geometry',result),('Valid',valid),('Hub Shift',g.xyz(*delta))):g.bind(value,out.inputs[key])
    return g.g


